<?php
 namespace Pterodactyl\Services\Dezerx\DiscordBot; use Predis\Connection\ConnectionException; use Illuminate\Support\Facades\Redis; class RenderGate { private const SLOTS = 2; private const WAIT_SECONDS = 1; private const HOLD_SECONDS = 20; private static float $fullUntil = 0.0; public static function run(callable $render): mixed { $wait = microtime(true) < self::$fullUntil ? 0 : self::WAIT_SECONDS; try { return Redis::funnel('dzb:render-gate') ->limit(self::SLOTS) ->releaseAfter(self::HOLD_SECONDS) ->block($wait) ->then($render, function () { self::$fullUntil = microtime(true) + 2; return null; }); } catch (ConnectionException) { return $render(); } } } 